namespace {
using V=rapidjson::Value;using A=rapidjson::Document::AllocatorType;
struct MailTransaction {
    gyu::db::CDatabaseSql*& slot;
    gyu::db::CDatabaseSql* previous;
    MailTransaction(gyu::db::CDatabaseSql*& target,gyu::db::CDatabaseSql* db):slot(target),previous(target){slot=db;}
    ~MailTransaction(){slot=previous;}
};
struct Range { const V& value; V::ConstValueIterator begin() const{return value.Begin();} V::ConstValueIterator end() const{return value.End();} };
Range Array(const V& v){return {v};}
struct Recipe {int id=0,item=0,output=0,realm=0,series=0,level=0,time=0,limit=0,count=0;std::vector<std::pair<int,int>> costs;};
struct Effect {int id=0,item=0,limit=0;std::string group;std::vector<int> positions;std::vector<std::pair<int,int>> attrs;};
struct Definitions {std::map<int,Recipe> recipes;std::map<int,int> learning;std::map<int,Effect> effects;std::map<int,int> prices;};
struct State {int64 revision=0,finish=0,duration=0;int recipe=0,count=0;std::string costs="[]";std::set<int> learned;std::map<int,int> uses;};
std::string Q(const std::string& s){std::string out="'";for(char c:s){out+=c;if(c=='\'')out+='\'';}return out+"'";}
void SQL(gyu::db::CDatabaseSql* db,const std::string& sql){if(!db->Query(sql.c_str()))throw std::runtime_error("炼丹存档失败");}
int N(const V& v,const char* key){if(!v.IsObject()||!v.HasMember(key)||!v[key].IsInt())throw std::runtime_error(std::string("炼丹配置整数缺失：")+key);return v[key].GetInt();}
std::string T(const V& v,const char* key){if(!v.IsObject()||!v.HasMember(key)||!v[key].IsString())throw std::runtime_error(std::string("炼丹配置文本缺失：")+key);return v[key].GetString();}
rapidjson::Document Read(const char* file){std::ifstream f(std::string("json/")+file);if(!f)throw std::runtime_error(std::string("炼丹配置缺失：")+file);std::ostringstream s;s<<f.rdbuf();rapidjson::Document d;d.Parse(s.str().c_str());if(d.HasParseError()||!d.IsArray())throw std::runtime_error("炼丹配置格式错误");return d;}
std::string Encode(const V& v){rapidjson::StringBuffer b;rapidjson::Writer<rapidjson::StringBuffer> w(b);v.Accept(w);return b.GetString();}
void Text(V& o,const char* key,const std::string& v,A& a){o.AddMember(V(key,a),V(v.c_str(),a),a);}
std::vector<std::pair<int,int>> Pairs(const V& r,const char* key){if(!r.HasMember(key)||!r[key].IsArray())throw std::runtime_error("炼丹材料/效果格式错误");std::vector<std::pair<int,int>> out;std::set<int> ids;for(const auto& p:Array(r[key])){if(!p.IsArray()||p.Size()!=2||!p[0].IsInt()||!p[1].IsInt()||p[0].GetInt()<1||p[1].GetInt()<1||!ids.insert(p[0].GetInt()).second)throw std::runtime_error("炼丹材料/效果重复或非正数");out.emplace_back(p[0].GetInt(),p[1].GetInt());}return out;}
Definitions Config(){Definitions c;auto r=Read("dongfu_alchemy_recipe.json");for(const auto& x:Array(r))if(N(x,"enabled")==1){Recipe p;p.id=N(x,"id");p.item=N(x,"learn_item_id");p.output=N(x,"output_item_id");p.realm=N(x,"realm_id");p.series=N(x,"series_id");p.level=N(x,"use_jingjie_id");p.time=N(x,"duration_seconds");p.limit=N(x,"batch_limit");p.count=N(x,"output_count");p.costs=Pairs(x,"cost_items");if(p.level<1||p.level>550||p.time<1||p.limit<1||p.limit>999||p.count<1||p.count*p.limit>65535||p.costs.empty()||!SingletonItemManager::instance().GetItem(p.item)||!SingletonItemManager::instance().GetItem(p.output)||!c.recipes.emplace(p.id,p).second||!c.learning.emplace(p.item,p.id).second)throw std::runtime_error("丹方引用或数量错误");for(auto cost:p.costs)if(!SingletonItemManager::instance().GetItem(cost.first))throw std::runtime_error("炼丹材料不存在");}
auto e=Read("dongfu_effect.json");for(const auto& x:Array(e))if(N(x,"enabled")==1){Effect p;p.id=N(x,"id");p.item=N(x,"item_id");p.limit=N(x,"limit_count");p.group=T(x,"limit_group");p.attrs=Pairs(x,"attributes");if(!x.HasMember("target_positions")||!x["target_positions"].IsArray())throw std::runtime_error("丹药站位配置缺失");std::set<int> seen;for(const auto& v:Array(x["target_positions"])){if(!v.IsInt()||v.GetInt()<0||v.GetInt()>5||!seen.insert(v.GetInt()).second)throw std::runtime_error("丹药站位错误");p.positions.push_back(v.GetInt());}if(p.limit<1||p.group.empty()||p.positions.empty()||p.attrs.empty()||!c.effects.emplace(p.item,p).second)throw std::runtime_error("丹药效果配置错误");for(auto attr:p.attrs)if((seen.count(0)&&(seen.size()!=1||(attr.first!=34&&attr.first!=35)))||(!seen.count(0)&&attr.first>33))throw std::runtime_error("丹药战斗与生产属性范围错误");}
auto shops=Read("dongfu_material_shop.json");for(const auto& x:Array(shops))if(N(x,"enabled")==1){int id=N(x,"item_id"),price=N(x,"price_gold");if(price<0||!SingletonItemManager::instance().GetItem(id)||!c.prices.emplace(id,price).second)throw std::runtime_error("材料商店配置错误");}for(const auto& p:c.recipes)if(!c.effects.count(p.second.output))throw std::runtime_error("丹药未配置效果");return c;}
const Definitions& Data(){static const auto c=Config();return c;}
void Ensure(gyu::db::CDatabaseSql* db){if(!db->ExecuteScript("CREATE TABLE IF NOT EXISTS unity_alchemy(role_id INTEGER PRIMARY KEY REFERENCES role_info(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 0,recipe_id INTEGER NOT NULL DEFAULT 0,count INTEGER NOT NULL DEFAULT 0,finish_ms INTEGER NOT NULL DEFAULT 0,costs TEXT NOT NULL DEFAULT '[]',duration_ms INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS unity_alchemy_learn(role_id INTEGER NOT NULL REFERENCES role_info(id) ON DELETE CASCADE,recipe_id INTEGER NOT NULL,PRIMARY KEY(role_id,recipe_id));CREATE TABLE IF NOT EXISTS unity_alchemy_use(role_id INTEGER NOT NULL REFERENCES role_info(id) ON DELETE CASCADE,item_id INTEGER NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(role_id,item_id));CREATE TABLE IF NOT EXISTS unity_alchemy_request(role_id INTEGER NOT NULL REFERENCES role_info(id) ON DELETE CASCADE,request_id TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(role_id,request_id));"))throw std::runtime_error("炼丹存档初始化失败");
    SQL(db,"PRAGMA table_info(unity_alchemy)");bool duration=false;while(char** column=db->GetRow())if(std::string(column[1])=="duration_ms")duration=true;
    if(!duration)SQL(db,"ALTER TABLE unity_alchemy ADD COLUMN duration_ms INTEGER NOT NULL DEFAULT 0");
}
State Get(CUser* u,gyu::db::CDatabaseSql* db){State s;std::string role=std::to_string(u->GetRoleId());SQL(db,"INSERT OR IGNORE INTO unity_alchemy(role_id) VALUES("+role+")");SQL(db,"SELECT revision,recipe_id,count,finish_ms,costs,duration_ms FROM unity_alchemy WHERE role_id="+role);auto row=db->GetRow();if(!row)throw std::runtime_error("炼丹角色存档缺失");s.revision=atoll(row[0]);s.recipe=atoi(row[1]);s.count=atoi(row[2]);s.finish=atoll(row[3]);s.costs=row[4];s.duration=atoll(row[5]);
    // Existing saves never recorded the start duration. Backfill a fixed base
    // duration once, retaining the original deadline and all paid materials.
    if(s.recipe&&s.duration<=0){s.duration=static_cast<int64>(Data().recipes.at(s.recipe).time)*s.count*1000;SQL(db,"UPDATE unity_alchemy SET duration_ms="+std::to_string(s.duration)+" WHERE role_id="+role);}
    SQL(db,"SELECT recipe_id FROM unity_alchemy_learn WHERE role_id="+role);while((row=db->GetRow()))s.learned.insert(atoi(row[0]));SQL(db,"SELECT item_id,count FROM unity_alchemy_use WHERE role_id="+role);while((row=db->GetRow()))s.uses[atoi(row[0])]=atoi(row[1]);return s;}
SUnityAlchemyBonus Bonus(const State& s){SUnityAlchemyBonus b;std::array<std::map<int,int64>,6> sums;for(const auto& used:s.uses){auto it=Data().effects.find(used.first);if(it==Data().effects.end())throw std::runtime_error("已服用丹药配置失效");for(int pos:it->second.positions)for(auto attr:it->second.attrs){int64 amount=static_cast<int64>(attr.second)*used.second;sums[pos][attr.first]+=amount;if(sums[pos][attr.first]>INT_MAX)throw std::overflow_error("丹药累计属性溢出");}}for(int pos=1;pos<=5;++pos)for(auto v:sums[pos]){SAttrData a;a.attrType=v.first;a.attrValue=static_cast<int>(v.second);b.positions[pos].push_back(a);}b.cultivation=static_cast<int>(sums[0][34]);b.spirit=static_cast<int>(sums[0][35]);return b;}
int64 UsedInGroup(const State& s,const std::string& group){int64 used=0;for(auto v:s.uses)if(Data().effects.at(v.first).group==group)used+=v.second;return used;}
void RecordUse(CUser* u,gyu::db::CDatabaseSql* db,State& s,int item,int count){if(!count)return;s.uses[item]+=count;u->m_unityAlchemyBonus=Bonus(s);SQL(db,"INSERT INTO unity_alchemy_use VALUES("+std::to_string(u->GetRoleId())+","+std::to_string(item)+","+std::to_string(s.uses[item])+") ON CONFLICT(role_id,item_id) DO UPDATE SET count=excluded.count");}
std::set<int> Shop(CUser* u,const State& s){std::set<int> result;for(const auto& r:Data().recipes)if(r.second.level<=u->GetJingJie()&&!s.learned.count(r.first))result.insert(r.second.item);for(auto v:Data().prices)if(!Data().learning.count(v.first))result.insert(v.first);return result;}
void Pack(CUser* u){CNetMessage m;m.SetType(PRO_ROLE_PACKAGE);u->MakePack(m);SingletonSocket::instance().SendMsg(u->GetSock(),m);}
void Reply(CUser* u,const State& s,unsigned char op,const std::string& request,const std::string& error,const std::string& result){rapidjson::Document d;d.SetObject();auto& a=d.GetAllocator();d.AddMember("schema",1,a);d.AddMember("operation",op,a);Text(d,"request_id",request,a);Text(d,"revision",std::to_string(s.revision),a);Text(d,"server_ms",std::to_string(CUnityJingJieService::NowMs()),a);Text(d,"finish_ms",std::to_string(s.finish),a);Text(d,"duration_ms",std::to_string(s.duration),a);Text(d,"gold",std::to_string(u->GetMoney()),a);Text(d,"error",error,a);Text(d,"result",result,a);d.AddMember("recipe_id",s.recipe,a);d.AddMember("count",s.count,a);d.AddMember("jingjie_id",u->GetJingJie(),a);d.AddMember("craft_reduction_bp",CUnitySpiritService::CraftReduction(u),a);V learned(rapidjson::kArrayType),owned(rapidjson::kArrayType),used(rapidjson::kArrayType),shop(rapidjson::kArrayType);for(int id:s.learned)learned.PushBack(id,a);std::set<int> ids;for(auto p:Data().recipes){ids.insert(p.second.item);ids.insert(p.second.output);for(auto cost:p.second.costs)ids.insert(cost.first);}for(int id:ids){V pair(rapidjson::kArrayType);pair.PushBack(id,a);pair.PushBack(u->GetMaterial(id),a);owned.PushBack(pair,a);}for(auto v:s.uses){V pair(rapidjson::kArrayType);pair.PushBack(v.first,a);pair.PushBack(v.second,a);used.PushBack(pair,a);}for(int id:Shop(u,s))shop.PushBack(id,a);d.AddMember("learned",learned,a);d.AddMember("owned",owned,a);d.AddMember("used",used,a);d.AddMember("shop",shop,a);CNetMessage m;m.SetType(327);m<<static_cast<uint8>(128)<<Encode(d);SingletonSocket::instance().SendMsg(u->GetSock(),m);}
}
void CUnityAlchemyService::Load(CUser* u){if(!u)return;CGetDbConnect c;auto db=c.GetDbConnect();if(!db||!db->IsSqlite())return;try{Ensure(db);u->m_unityAlchemyBonus=Bonus(Get(u,db));}catch(const std::exception& e){cout<<"[UnityAlchemy] load: "<<e.what()<<endl;u->m_unityAlchemyBonus=SUnityAlchemyBonus();}}
bool CUnityAlchemyService::IsItem(int id){return Data().learning.count(id)||Data().effects.count(id);}
int CUnityAlchemyService::CultivationBonus(CUser* u){return u?u->m_unityAlchemyBonus.cultivation:0;}
int CUnityAlchemyService::SpiritBonus(CUser* u){return u?u->m_unityAlchemyBonus.spirit:0;}
std::vector<SAttrData> CUnityAlchemyService::CombatAttributes(CUser* u,int pos){return u&&pos>=1&&pos<=5?u->m_unityAlchemyBonus.positions[pos]:std::vector<SAttrData>();}
bool CUnityAlchemyService::OverflowMail(CUser* u,int item,int count,const char* message){
    if(!u||!u->m_unityAlchemyDb||!u->m_unityAlchemyDb->IsSqlite()||count<1)return false;
    SMailData mail;mail.AddAward(item,0,count);std::string attachment;MakeMailAttachStr(attachment,&mail);
    SQL(u->m_unityAlchemyDb,"INSERT INTO xin_shi (money,YB,bdYB,attachment,from_id,to_id,gmtime,time,shenhun,deleted,from_name,message) VALUES (0,0,0,"+Q(attachment)+",0,"+std::to_string(u->GetRoleId())+",0,datetime('now'),0,0,'System',"+Q(message?message:"炼丹奖励：背包已满")+")");
    return true;
}
void CUnityAlchemyService::UseFromBag(CUser* u,int item,int n){rapidjson::Document p;p.SetObject();auto& a=p.GetAllocator();static std::atomic<unsigned long long> sequence{0};Text(p,"request_id","bag-"+std::to_string(CUnityJingJieService::NowMs())+"-"+std::to_string(++sequence),a);p.AddMember("item_id",item,a);p.AddMember("quantity",n,a);Handle(u,Data().learning.count(item)?1:5,Encode(p));}
void CUnityAlchemyService::Handle(CUser* u,unsigned char op,const std::string& payload){if(!u)return;boost::recursive_mutex::scoped_lock lock(u->m_mutex);CGetDbConnect c;auto db=c.GetDbConnect();if(!db||!db->IsSqlite())return;MailTransaction mailTransaction(u->m_unityAlchemyDb,db);State s;std::string request,bag,result;uint32 money=u->GetMoney();bool tx=false,committed=false;auto bonus=u->m_unityAlchemyBonus;
try{if(op>6||payload.size()>2048)throw std::runtime_error("炼丹操作格式错误");rapidjson::Document input;input.Parse(payload.c_str());if(input.HasParseError()||!input.IsObject())throw std::runtime_error("炼丹请求格式错误");request=T(input,"request_id");if(request.empty()||request.size()>64)throw std::runtime_error("炼丹请求标识错误");Ensure(db);if(op==4||op==5){CUnityJingJieService::Instance().Flush(u);if(!CUnitySpiritService::ChangeResource(u,0))throw std::runtime_error("旧产速收益同步失败");}SQL(db,"SAVEPOINT alchemy_command");tx=true;s=Get(u,db);if(op){SQL(db,"SELECT payload,result FROM unity_alchemy_request WHERE role_id="+std::to_string(u->GetRoleId())+" AND request_id="+Q(request));auto replay=db->GetRow();if(replay){if(std::to_string(op)+":"+payload!=replay[0])throw std::runtime_error("重复炼丹请求内容不一致");result=replay[1];SQL(db,"RELEASE alchemy_command");tx=false;Reply(u,s,op,request,"",result);Pack(u);return;}if(input.HasMember("revision")&&T(input,"revision")!=std::to_string(s.revision))throw std::runtime_error("炼丹状态已变化，请重试");u->GetPackage(bag);if(bag.empty())throw std::runtime_error("背包快照失败");int n=input.HasMember("quantity")?N(input,"quantity"):1;if(n<1||n>999)throw std::runtime_error("数量须为1～999");
if(op==1){int item=N(input,"item_id");auto it=Data().learning.find(item);if(it==Data().learning.end())throw std::runtime_error("丹方不存在");const auto& r=Data().recipes.at(it->second);if(s.learned.count(r.id))throw std::runtime_error("该丹方已学习");if(u->GetJingJie()<r.level)throw std::runtime_error("境界未达到丹方使用等级");if(!u->DelPackageById(item,1))throw std::runtime_error("背包没有对应丹方");SQL(db,"INSERT INTO unity_alchemy_learn VALUES("+std::to_string(u->GetRoleId())+","+std::to_string(r.id)+")");s.learned.insert(r.id);}
else if(op==2){if(s.recipe)throw std::runtime_error("请先完成或取消当前炼丹");int id=N(input,"recipe_id");auto it=Data().recipes.find(id);if(it==Data().recipes.end()||!s.learned.count(id))throw std::runtime_error("尚未学习该丹方");const auto& r=it->second;if(u->GetJingJie()<r.level||n>r.limit)throw std::runtime_error("境界或数量不符合丹方要求");for(auto v:r.costs)if(static_cast<int64>(v.second)*n>INT_MAX||u->GetMaterial(v.first)<v.second*n)throw std::runtime_error("炼丹材料不足");rapidjson::Document paid;paid.SetArray();auto& pa=paid.GetAllocator();for(auto v:r.costs){if(!u->DelPackageById(v.first,v.second*n))throw std::runtime_error("炼丹扣材失败");V pair(rapidjson::kArrayType);pair.PushBack(v.first,pa);pair.PushBack(v.second*n,pa);paid.PushBack(pair,pa);}int bp=CUnitySpiritService::CraftReduction(u);s.recipe=id;s.count=n;s.costs=Encode(paid);s.duration=spirit::Duration(static_cast<int64>(r.time)*n*1000,bp);s.finish=CUnityJingJieService::NowMs()+s.duration;}
else if(op==3){if(!s.recipe||CUnityJingJieService::NowMs()>=s.finish)throw std::runtime_error("当前炼丹不可取消");rapidjson::Document paid;paid.Parse(s.costs.c_str());if(paid.HasParseError()||!paid.IsArray())throw std::runtime_error("炼丹扣材快照错误");for(const auto& p:Array(paid)){int id=p[0].GetInt(),left=p[1].GetInt()/2;while(left>0){int amount=std::min(left,65535);if(!u->AddPackage(id,static_cast<uint16>(amount),nullptr,"炼丹取消返还材料"))throw std::runtime_error("炼丹返材失败");left-=amount;}}s.recipe=0;s.count=0;s.finish=0;s.duration=0;s.costs="[]";}
else if(op==4){if(!s.recipe||CUnityJingJieService::NowMs()<s.finish)throw std::runtime_error("炼丹尚未完成");const auto& r=Data().recipes.at(s.recipe);const auto& e=Data().effects.at(r.output);int count=r.count*s.count;int consumed=static_cast<int>(std::min<int64>(count,std::max<int64>(0,e.limit-UsedInGroup(s,e.group))));int sold=count-consumed;const auto* item=SingletonItemManager::instance().GetItem(r.output);if(!item||item->jiage<0)throw std::runtime_error("丹药出售价格错误");int64 gold=static_cast<int64>(sold)*item->jiage;if(static_cast<int64>(u->GetMoney())+gold>INT_MAX)throw std::runtime_error("金币已达上限，请先使用部分金币后领取");RecordUse(u,db,s,r.output,consumed);u->m_money+=static_cast<int>(gold);rapidjson::Document claim;claim.SetObject();auto& ca=claim.GetAllocator();claim.AddMember("item_id",r.output,ca);claim.AddMember("count",count,ca);claim.AddMember("used",consumed,ca);claim.AddMember("sold",sold,ca);Text(claim,"gold",std::to_string(gold),ca);claim.AddMember("mailed",0,ca);result=Encode(claim);s.recipe=0;s.count=0;s.finish=0;s.duration=0;s.costs="[]";}
else if(op==5){int item=N(input,"item_id");auto it=Data().effects.find(item);if(it==Data().effects.end())throw std::runtime_error("该道具不是丹药");const auto& e=it->second;int64 used=UsedInGroup(s,e.group);if(n>e.limit-used)throw std::runtime_error("已达丹药服用上限");auto recipe=std::find_if(Data().recipes.begin(),Data().recipes.end(),[&](const auto& r){return r.second.output==item;});if(recipe==Data().recipes.end()||u->GetJingJie()<recipe->second.level)throw std::runtime_error("境界未达到丹药使用等级");if(!u->DelPackageById(item,n))throw std::runtime_error("丹药数量不足");RecordUse(u,db,s,item,n);}
else if(op==6){int item=N(input,"item_id");if(!Shop(u,s).count(item)||!Data().prices.count(item))throw std::runtime_error("该商品当前不可购买");int64 price=static_cast<int64>(Data().prices.at(item))*n;if(price>u->GetMoney())throw std::runtime_error("金币不足");u->m_money-=static_cast<uint32>(price);if(!u->AddPackage(item,static_cast<uint16>(n),nullptr,"材料商店商品：背包满，发送至邮件"))throw std::runtime_error("商品发放失败");}
++s.revision;SQL(db,"UPDATE unity_alchemy SET revision="+std::to_string(s.revision)+",recipe_id="+std::to_string(s.recipe)+",count="+std::to_string(s.count)+",finish_ms="+std::to_string(s.finish)+",duration_ms="+std::to_string(s.duration)+",costs="+Q(s.costs)+" WHERE role_id="+std::to_string(u->GetRoleId()));std::string after;u->GetPackage(after);SQL(db,"UPDATE role_info SET package="+Q(after)+",money="+std::to_string(u->GetMoney())+" WHERE id="+std::to_string(u->GetRoleId()));SQL(db,"INSERT INTO unity_alchemy_request VALUES("+std::to_string(u->GetRoleId())+","+Q(request)+","+Q(std::to_string(op)+":"+payload)+","+Q(result)+")");}
SQL(db,"RELEASE alchemy_command");tx=false;committed=true;if(op==4||op==5){CUnitySpiritService::Load(u);CUnityJingJieService::Instance().Snapshot(u);for(uint8 pos=1;pos<=5;++pos)u->UpdateZhenFaPetInfo(pos);}if(op){Pack(u);u->SendUpdateInfo(EUUT_Money);}Reply(u,s,op,request,"",result);
}catch(const std::exception& e){if(tx){db->Query("ROLLBACK TO alchemy_command");db->Query("RELEASE alchemy_command");}if(!committed){u->m_money=money;u->m_unityAlchemyBonus=bonus;if(!bag.empty())u->SetPackage(&bag[0]);}try{s=Get(u,db);Pack(u);Reply(u,s,op,request,e.what(),"");}catch(const std::exception& nested){cout<<"[UnityAlchemy] reply: "<<nested.what()<<endl;}}}
